import{f as e,g as t,l as n,n as r,p as i,s as a}from"./index-Dz1t9-Mx.js";import{t as o}from"./navigate-CpeDEQ7S.js";var s={name:`FrontendHtmlCssPage`,methods:{handleNav(e){o(e)}}},c={class:`htmlcss-page`,style:{"--color-accent":`#7c5cfc`}},l={class:`page`},u={class:`topbar`},d={class:`links`};function f(r,o,s,f,p,m){return t(),e(`div`,c,[n(`div`,l,[n(`div`,u,[o[2]||=n(`h1`,null,`🎨 HTML & CSS`,-1),n(`div`,d,[n(`a`,{href:`#`,onClick:o[0]||=a(e=>m.handleNav(`/frontend/hub`),[`prevent`])},`← Frontend`),n(`a`,{href:`#`,onClick:o[1]||=a(e=>m.handleNav(`/`),[`prevent`])},`Trang chủ`)])]),o[3]||=i(`<p class="desc" data-v-39af235a>Từ semantic HTML đến CSS hiện đại: Flexbox, Grid, Animation, Custom Properties, BEM, và 25+ kỹ thuật thực tế.</p><div class="section" data-v-39af235a><h2 data-v-39af235a>📐 HTML5 Semantic</h2><p data-v-39af235a>Các thẻ semantic giúp SEO, accessibility, và maintain code tốt hơn.</p><pre data-v-39af235a><code data-v-39af235a>&lt;header&gt; &lt;nav&gt; &lt;main&gt; &lt;section&gt; &lt;article&gt; &lt;aside&gt; &lt;footer&gt;</code></pre><div class="grid-2" data-v-39af235a><div class="card" data-v-39af235a><h4 data-v-39af235a>&lt;header&gt;</h4><p data-v-39af235a>Đầu trang, chứa logo, navigation, search bar</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>&lt;nav&gt;</h4><p data-v-39af235a>Điều hướng chính, menu links</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>&lt;main&gt;</h4><p data-v-39af235a>Nội dung chính, chỉ 1 lần/trang</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>&lt;article&gt;</h4><p data-v-39af235a>Nội dung độc lập, có thể tái sử dụng</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>&lt;section&gt;</h4><p data-v-39af235a>Nhóm nội dung theo chủ đề</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>&lt;aside&gt;</h4><p data-v-39af235a>Nội dung liên quan, sidebar</p></div></div></div><div class="section" data-v-39af235a><h2 data-v-39af235a>📦 CSS Box Model &amp; Units</h2><pre data-v-39af235a><code data-v-39af235a>* { box-sizing: border-box; } /* content-box vs border-box */</code></pre><p data-v-39af235a><strong data-v-39af235a>Units:</strong> <code data-v-39af235a>px</code> (cố định), <code data-v-39af235a>rem</code> (dựa trên root font-size), <code data-v-39af235a>em</code> (dựa trên parent), <code data-v-39af235a>%</code>, <code data-v-39af235a>vw/vh</code> (viewport), <code data-v-39af235a>ch</code> (độ rộng chữ), <code data-v-39af235a>fr</code> (fraction trong grid)</p></div><div class="section" data-v-39af235a><h2 data-v-39af235a>🧩 Flexbox</h2><p data-v-39af235a>Bố cục 1 chiều — dùng cho navigation, card rows, center content.</p><pre data-v-39af235a><code data-v-39af235a>.container {
  display: flex;
  justify-content: center; /* flex-start | center | space-between | space-around */
  align-items: center;     /* stretch | center | flex-start */
  gap: 1rem;               /* khoảng cách giữa các item */
  flex-wrap: wrap;         /* xuống dòng khi hết chỗ */
}
.item { flex: 1; }          /* chia đều không gian */</code></pre></div><div class="section" data-v-39af235a><h2 data-v-39af235a>🔲 CSS Grid</h2><p data-v-39af235a>Bố cục 2 chiều — dùng cho layout chính, gallery, dashboard.</p><pre data-v-39af235a><code data-v-39af235a>.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);  /* 3 cột bằng nhau */
  grid-template-columns: 200px 1fr;        /* sidebar + content */
  gap: 1rem;
}
.item { grid-column: span 2; }            /* chiếm 2 cột */
.item { grid-area: 1 / 1 / 3 / 3; }       /* row-start / col-start / row-end / col-end */</code></pre></div><div class="section" data-v-39af235a><h2 data-v-39af235a>🎭 CSS Custom Properties (Variables)</h2><pre data-v-39af235a><code data-v-39af235a>:root {
  --primary: #6366f1;
  --radius: 8px;
  --shadow: 0 2px 8px rgba(0,0,0,0.1);
}
.btn { background: var(--primary); border-radius: var(--radius); }
/* Fallback: var(--primary, blue) */</code></pre></div><div class="section" data-v-39af235a><h2 data-v-39af235a>✨ CSS Animations &amp; Transitions</h2><pre data-v-39af235a><code data-v-39af235a>.btn {
  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.3s;
}
.btn:hover { transform: translateY(-3px) scale(1.02); box-shadow: 0 8px 24px rgba(0,0,0,0.15); }

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}
.box { animation: fadeIn 0.5s ease forwards; }</code></pre></div><div class="section" data-v-39af235a><h2 data-v-39af235a>🧱 BEM Methodology</h2><pre data-v-39af235a><code data-v-39af235a>/* Block__Element--Modifier */
.card { }                    /* Block */
.card__title { }             /* Element */
.card__title--highlight { }  /* Modifier */
.card--featured { }          /* Modifier của Block */</code></pre></div><div class="section" data-v-39af235a><h2 data-v-39af235a>🎪 25+ CSS Techniques</h2><div class="grid-2" data-v-39af235a><div class="card" data-v-39af235a><h4 data-v-39af235a>Hover Effect</h4><p data-v-39af235a><code data-v-39af235a>cubic-bezier</code> spring + glow shadow</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Tooltip</h4><p data-v-39af235a><code data-v-39af235a>[data-tooltip]::after</code> CSS-only</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Glassmorphism</h4><p data-v-39af235a><code data-v-39af235a>backdrop-filter: blur(14px)</code></p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Neumorphism</h4><p data-v-39af235a>Inset/outset soft shadows</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Card Hover</h4><p data-v-39af235a>Sweep shimmer <code data-v-39af235a>::before</code></p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Ripple Effect</h4><p data-v-39af235a>JS + <code data-v-39af235a>@keyframes</code></p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Skeleton</h4><p data-v-39af235a>Shimmer gradient animation</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Gradient Text</h4><p data-v-39af235a><code data-v-39af235a>background-clip: text</code></p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Flip Card</h4><p data-v-39af235a><code data-v-39af235a>perspective + rotateY</code></p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Accordion</h4><p data-v-39af235a>Checkbox hack CSS-only</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Modal</h4><p data-v-39af235a><code data-v-39af235a>:target</code> pseudo-class</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Toggle Switch</h4><p data-v-39af235a>Checkbox styling + spring</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Custom Scrollbar</h4><p data-v-39af235a><code data-v-39af235a>::-webkit-scrollbar</code></p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Masonry</h4><p data-v-39af235a><code data-v-39af235a>columns: 3</code></p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Parallax</h4><p data-v-39af235a><code data-v-39af235a>background-attachment</code></p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Loading Spinner</h4><p data-v-39af235a>Border rotation keyframe</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Timeline</h4><p data-v-39af235a><code data-v-39af235a>::before</code> line + dots</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Animated Button</h4><p data-v-39af235a>Slide fill <code data-v-39af235a>::before</code></p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Sticky Header</h4><p data-v-39af235a><code data-v-39af235a>position: sticky</code></p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Dropdown</h4><p data-v-39af235a>CSS hover menu</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Sidebar</h4><p data-v-39af235a>Checkbox toggle animation</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Responsive Nav</h4><p data-v-39af235a>Media query + hamburger</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Image Zoom</h4><p data-v-39af235a><code data-v-39af235a>scale(1.25)</code> overflow hidden</p></div><div class="card" data-v-39af235a><h4 data-v-39af235a>Carousel</h4><p data-v-39af235a>JS + CSS <code data-v-39af235a>translateX</code></p></div></div></div>`,9)])])}var p=r(s,[[`render`,f],[`__scopeId`,`data-v-39af235a`]]);export{p as default};